// leftovers from interrupted runs so tests start from a clean slate.
const purgeDomains = (...hostnames: string[]) =>
  Effect.gen(function* () {
    const { accountId } = yield* yield* CloudflareEnvironment;
    yield* Effect.forEach(hostnames, (hostname) =>
